const title = $json.title;
const link = $json.link;
const content = $json.content;
const website_tag =$json.website_tag

const date = new Date($json.date).toLocaleString("en-GB", {
  day: "2-digit",
  month: "short",
  year: "numeric",
  hour: "2-digit",
  minute: "2-digit"
});

let priority = "⚪ Low";

const text = title.toLowerCase();

if (
  text.includes("zero-day") ||
  text.includes("ransomware") ||
  text.includes("active exploit") ||
  text.includes("critical") ||
  text.includes("rce")
) {
  priority = "🔴 Critical";
}
else if (
  text.includes("cve") ||
  text.includes("vulnerability") ||
  text.includes("patch") ||
  text.includes("exploit")
) {
  priority = "🟠 High";
}
else if (
  text.includes("security") ||
  text.includes("research")
) {
  priority = "🟡 Medium";
}

const shortContent =
  content.length > 450
    ? content.substring(0, 450) + "..."
    : content;

const message = `

${priority }

📌 ${title}

${date}
${website_tag}

📄 Description:
${shortContent}

🔗 Read more:
${link}
`;

return {
  json: {
    message
  }
};

