const data = $input.first().json;

return data.items.map(vulnerability => {
  const score = Number(vulnerability.baseScore);

  let severity;

  if (score >= 9) {
    severity = 'CRITICAL';
  } else if (score >= 7) {
    severity = 'HIGH';
  } else if (score >= 4) {
    severity = 'MEDIUM';
  } else {
    severity = 'LOW';
  }

  return {
    json: {
      euvd_id: vulnerability.id,
      cve_id: vulnerability.aliases || '',
      severity,
      score,
      description: vulnerability.description,
      datePublished: vulnerability.datePublished,
      dateUpdated: vulnerability.dateUpdated,
      references: vulnerability.references || '',
      vendor: vulnerability.enisaIdVendor?.[0]?.vendor?.name || '',
      epss: vulnerability.epss
    }
