const items = $input.all();

return items.map(item => {
  const input = item.json;

  let report;

  // Case 1: AI already returned a parsed JSON object
  if (
    input.ai_report &&
    typeof input.ai_report === 'object' &&
    !Array.isArray(input.ai_report)
  ) {
    report = input.ai_report;
  } else {
    const raw =
      input.ai_report ??
      input.output ??
      input.text ??
      input.response ??
      input.content ??
      '';

    let cleaned = String(raw)
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    // Find the first JSON object in the AI response
    const firstBrace = cleaned.indexOf('{');

    if (firstBrace === -1) {
      throw new Error(
        'AI did not return a JSON object. Response starts with: ' +
        cleaned.substring(0, 200)
      );
    }

    cleaned = cleaned.substring(firstBrace);

    // Try to find the matching closing brace
    let depth = 0;
    let inString = false;
    let escaped = false;
    let endIndex = -1;

    for (let i = 0; i < cleaned.length; i++) {
      const char = cleaned[i];

      if (escaped) {
        escaped = false;
        continue;
      }

      if (char === '\\' && inString) {
        escaped = true;
        continue;
      }

      if (char === '"') {
        inString = !inString;
        continue;
      }

      if (!inString) {
        if (char === '{') {
          depth++;
        } else if (char === '}') {
          depth--;

          if (depth === 0) {
            endIndex = i + 1;
            break;
          }
        }
      }
    }

    if (endIndex === -1) {
      throw new Error(
        'AI response contains an opening { but no complete JSON object.'
      );
    }

    cleaned = cleaned.substring(0, endIndex);

    try {
      report = JSON.parse(cleaned);
    } catch (error) {
      throw new Error(
        'Failed to parse AI report JSON: ' +
        error.message +
        '\n\nAI response begins with:\n' +
        cleaned.substring(0, 500)
      );
    }
  }

  return {
    json: report
  };
});

const input = $input.first().json;

const topics = input.report_summary?.top_topics ?? [];
const articles = input.articles ?? input.stories ?? input.news ?? [];

const topicCounts = {};

for (const topic of topics) {
  topicCounts[topic] = 0;
}

for (const article of articles) {
  const topic =
    article.topic ??
    article.category ??
    article.field ??
    '';

  if (topic) {
    topicCounts[topic] = (topicCounts[topic] ?? 0) + 1;
  }
}

const topicAnalysis = Object.entries(topicCounts)
  .map(([topic, count]) => ({
    topic,
    count
  }))
  .sort((a, b) => b.count - a.count);

return [
  {
    json: {
      ...input,
      topic_analysis: topicAnalysis
    }
  }
];

