        ${esc(story.topic || '')}
        ${story.impact_level ? ` • ${esc(story.impact_level)}` : ''}
        ${story.importance_score ? ` • ${esc(story.importance_score)}/10` : ''}
      </div>
      <p>${esc(story.summary)}</p>
      ${
        story.url
          ? `<a href="${esc(story.url)}">${esc(story.source || 'Read source')} →</a>`
