`).join('');

// Create a simple CSS pie chart from topic percentages
const pieSegments = [];
let currentAngle = 0;

const chartValues = Array.isArray(chart.values)
  ? chart.values
  : topics.map(item => Number(item.count || 0));

const chartLabels = Array.isArray(chart.labels)
  ? chart.labels
  : topics.map(item => item.topic);

const totalChartValue = chartValues.reduce(
  (sum, value) => sum + Number(value || 0),
  0
);

if (totalChartValue > 0) {
  chartValues.forEach((value, index) => {
    const percentage = (Number(value) / totalChartValue) * 100;
    const start = currentAngle;
    const end = currentAngle + (percentage * 3.6);

    pieSegments.push({
      label: chartLabels[index] || '',
      percentage,
      start,
      end
    });

    currentAngle = end;
  });
}

const pieGradient = pieSegments.length
  ? `conic-gradient(
      ${pieSegments
        .map((segment, index) => {
          const colors = [
            '#2563eb',
            '#7c3aed',
            '#059669',
            '#d97706',
            '#dc2626',
            '#0891b2',
            '#db2777',
            '#65a30d',
            '#9333ea'
          ];

          return `${colors[index % colors.length]} ${segment.start}deg ${segment.end}deg`;
        })
        .join(', ')}
    )`
  : '#e5e7eb';

const pieLegend = pieSegments.map((segment, index) => {
  const colors = [
    '#2563eb',
    '#7c3aed',
    '#059669',
    '#d97706',
    '#dc2626',
    '#0891b2',
    '#db2777',
    '#65a30d',
    '#9333ea'
  ];

  return `
    <div class="legend-item">
      <span
        class="legend-color"
        style="background:${colors[index % colors.length]}"
      ></span>
      <span>
        ${esc(segment.label)}
        <strong>${segment.percentage.toFixed(1)}%</strong>
      </span>
    </div>
  `;
}).join('');

